mapper.select:
select i.id, i.introspect_id as introspectId, t.title as introspectTitle, i.occur_date as occurDate, i.content, i.sort_order as sortOrder, i.user_id as userId from mes_rec_introspect_item i left join mes_rec_introspect t on t.id = i.introspect_id and t.deleted_flag = 0
i.deleted_flag = 0 and i.user_id = #{param.userId}
and i.id = #{param.id}
and i.introspect_id = #{param.introspectId}
and date(i.occur_date) = date(#{param.occurDate})
and i.occur_date >= #{param.occurDateBegin}
and #{param.occurDateEnd} > i.occur_date
order by i.sort_order asc, i.id asc
